        return 0
    elif seq == []:
        return 0
    for i, elem in enumerate(seq):
        if x < elem: 
            return i
        elif x == elem:
            return i
        elif i == len(seq)-1:
            return i+1
        elif seq == []:
            return 0

def search(x, seq):
    if seq == []:
        return 0
    else:
        for i, elem in enumerate(seq):
            if x <= elem: 
                return i
            elif x == elem:
                return i
            elif i == len(seq)-1:
                return i+1

def search(x, seq):
    l=len(seq)
    if l==0:
        return 0
    for i in range(l):
        if x<=seq[i]:
            break
    if x>seq[l-1]:
        i=i+1
    return i

def search(x, seq):
    if seq == () or seq == []:
        return 0
    else:
        for i, elem in enumerate (seq):
            if x<=elem:
                return i
            elif x>seq[-1]:
                return len(seq)

def search(x, seq):
    """ Takes in a value x and a sorted sequence seq, and returns the
    position that x should go to such that the sequence remains sorted """
    seq = tuple(seq)
    if seq == ():
        return 0
    elif x > seq[len(seq)-1]:
        return len(seq)
    else:
        i = 0
        while i <= len(seq)-1:
            if x <= seq[i]:
                return i
            elif x > seq[i]:
                i += 1

